-- sql
WITH _hq_raw AS (SELECT created_at AS _hq_row_1, amount_cents AS _hq_row_2, NULL AS _hq_row_3, upper(region_code) AS _hq_row_4, amount_cents AS _hq_row_5 FROM analytics.orders WHERE tenant_id = $1),
_hq_source AS (SELECT (CASE WHEN pg_typeof(_hq_row_1) = 'date'::regtype THEN (_hq_row_1)::timestamp AT TIME ZONE 'UTC' ELSE (_hq_row_1)::timestamptz END) AS _hq_time, _hq_row_2 AS _hq_v0, _hq_row_3 AS _hq_a0, _hq_row_4 AS _hq_v1, _hq_row_5 AS _hq_a1 FROM _hq_raw WHERE (_hq_row_1 IS NOT NULL)),
_hq_bounds AS (SELECT * FROM (SELECT (CASE WHEN CAST($2 AS text) ~ '(Z|[+-][0-9]{2}:[0-9]{2})$' THEN CAST(CAST($2 AS text) AS timestamptz) ELSE CAST(CAST($2 AS text) AS timestamp) AT TIME ZONE 'UTC' END) AS _hq_lower) AS _hq_step0 CROSS JOIN LATERAL (SELECT (CASE WHEN CAST($3 AS text) ~ '(Z|[+-][0-9]{2}:[0-9]{2})$' THEN CAST(CAST($3 AS text) AS timestamptz) ELSE CAST(CAST($3 AS text) AS timestamp) AT TIME ZONE 'UTC' END) AS _hq_upper) AS _hq_step1 CROSS JOIN LATERAL (SELECT date_trunc('day', _hq_lower, 'UTC') AS _hq_first) AS _hq_step2 CROSS JOIN LATERAL (SELECT date_trunc('day', _hq_upper, 'UTC') AS _hq_last) AS _hq_step3),
_hq_series AS (SELECT (((_hq_first AT TIME ZONE 'UTC') + (generate_series(0, ((((_hq_last AT TIME ZONE 'UTC'))::date - ((_hq_first AT TIME ZONE 'UTC'))::date)::bigint + 1 + CAST(CASE WHEN (((_hq_last AT TIME ZONE 'UTC'))::date - ((_hq_first AT TIME ZONE 'UTC'))::date)::bigint + 1 > 500 THEN '[hypequery] Window series exceeds the effective result limit of 500 buckets.' ELSE '0' END AS integer) + 0 + CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, (((_hq_last AT TIME ZONE 'UTC'))::date - ((_hq_first AT TIME ZONE 'UTC'))::date)::bigint + 1 + CAST(CASE WHEN (((_hq_last AT TIME ZONE 'UTC'))::date - ((_hq_first AT TIME ZONE 'UTC'))::date)::bigint + 1 > 500 THEN '[hypequery] Window series exceeds the effective result limit of 500 buckets.' ELSE '0' END AS integer) + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer))) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((_hq_first AT TIME ZONE 'UTC') + (_hq_calendar_index + 1) * INTERVAL '1 day') AT TIME ZONE 'UTC') <= (((_hq_first AT TIME ZONE 'UTC') + (_hq_calendar_index) * INTERVAL '1 day') AT TIME ZONE 'UTC')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer) + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer)) - 1)) * INTERVAL '1 day') AT TIME ZONE 'UTC') AS _hq_period FROM _hq_bounds),
_hq_scanned AS (SELECT * FROM _hq_source CROSS JOIN _hq_bounds WHERE (_hq_time < (((_hq_last AT TIME ZONE 'UTC') + (1) * INTERVAL '1 day') AT TIME ZONE 'UTC') AND _hq_time >= LEAST(((((((_hq_first AT TIME ZONE 'UTC') + (1) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC') - (7) * INTERVAL '1 day') AT TIME ZONE 'UTC'), ((((((_hq_first AT TIME ZONE 'UTC') + (1) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC') - (7) * INTERVAL '1 day') AT TIME ZONE 'UTC')))),
_hq_skeleton AS (SELECT * FROM _hq_series),
_hq_fan0 AS (SELECT *, (((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (generate_series(0, (((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (7) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint + CAST(CASE WHEN ((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (7) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint > 1000 THEN '[hypequery] A window row contributes to more than 1000 buckets.' ELSE '0' END AS integer) + CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, ((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (7) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint + CAST(CASE WHEN ((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (7) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint > 1000 THEN '[hypequery] A window row contributes to more than 1000 buckets.' ELSE '0' END AS integer))) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (_hq_calendar_index + 1) * INTERVAL '1 day') AT TIME ZONE 'UTC') <= (((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (_hq_calendar_index) * INTERVAL '1 day') AT TIME ZONE 'UTC')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer)) - 1)) * INTERVAL '1 day') AT TIME ZONE 'UTC') AS _hq_period FROM _hq_scanned),
_hq_agg0 AS (SELECT _hq_period, percentile_cont(0.95) WITHIN GROUP (ORDER BY _hq_v0) AS _hq_m0 FROM _hq_fan0 WHERE _hq_period BETWEEN _hq_first AND _hq_last AND _hq_time >= ((((((_hq_period AT TIME ZONE 'UTC') + (1) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC') - (7) * INTERVAL '1 day') AT TIME ZONE 'UTC') GROUP BY _hq_period),
_hq_fan1 AS (SELECT *, (((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (generate_series(0, (((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (7) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint + CAST(CASE WHEN ((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (7) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint > 1000 THEN '[hypequery] A window row contributes to more than 1000 buckets.' ELSE '0' END AS integer) + CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, ((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (7) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint + CAST(CASE WHEN ((((((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (7) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'))::date - ((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC'))::date)::bigint > 1000 THEN '[hypequery] A window row contributes to more than 1000 buckets.' ELSE '0' END AS integer))) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (_hq_calendar_index + 1) * INTERVAL '1 day') AT TIME ZONE 'UTC') <= (((date_trunc('day', _hq_time, 'UTC') AT TIME ZONE 'UTC') + (_hq_calendar_index) * INTERVAL '1 day') AT TIME ZONE 'UTC')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer)) - 1)) * INTERVAL '1 day') AT TIME ZONE 'UTC') AS _hq_period FROM _hq_scanned),
_hq_agg1 AS (SELECT _hq_period, (ARRAY_AGG(_hq_v1 ORDER BY _hq_a1 DESC) FILTER (WHERE _hq_a1 IS NOT NULL))[1] AS _hq_m1 FROM _hq_fan1 WHERE _hq_period BETWEEN _hq_first AND _hq_last AND _hq_time >= ((((((_hq_period AT TIME ZONE 'UTC') + (1) * INTERVAL '1 day') AT TIME ZONE 'UTC') AT TIME ZONE 'UTC') - (7) * INTERVAL '1 day') AT TIME ZONE 'UTC') GROUP BY _hq_period),
_hq_values AS (SELECT (s._hq_period AT TIME ZONE 'UTC') AS period, m0._hq_m0 AS "rollingP95", m1._hq_m1 AS "rollingTop" FROM _hq_skeleton AS s LEFT JOIN _hq_agg0 AS m0 ON s._hq_period = m0._hq_period LEFT JOIN _hq_agg1 AS m1 ON s._hq_period = m1._hq_period),
_hq_result AS (SELECT "period", "rollingP95", "rollingTop" FROM _hq_values UNION ALL SELECT NULL AS "period", NULL AS "rollingP95", NULL AS "rollingTop" FROM _hq_bounds WHERE CAST(CASE WHEN (((_hq_last AT TIME ZONE 'UTC'))::date - ((_hq_first AT TIME ZONE 'UTC'))::date)::bigint + 1 > 500 THEN '[hypequery] Window series exceeds the effective result limit of 500 buckets.' ELSE '0' END AS integer) + 0 + CAST(CASE WHEN EXISTS (SELECT 1 FROM generate_series(0, (GREATEST(1, (((_hq_last AT TIME ZONE 'UTC'))::date - ((_hq_first AT TIME ZONE 'UTC'))::date)::bigint + 1 + CAST(CASE WHEN (((_hq_last AT TIME ZONE 'UTC'))::date - ((_hq_first AT TIME ZONE 'UTC'))::date)::bigint + 1 > 500 THEN '[hypequery] Window series exceeds the effective result limit of 500 buckets.' ELSE '0' END AS integer) + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer))) - 1) AS _hq_index_series(_hq_calendar_index) WHERE (((_hq_first AT TIME ZONE 'UTC') + (_hq_calendar_index + 1) * INTERVAL '1 day') AT TIME ZONE 'UTC') <= (((_hq_first AT TIME ZONE 'UTC') + (_hq_calendar_index) * INTERVAL '1 day') AT TIME ZONE 'UTC')) THEN '[hypequery] Time range crosses a skipped local calendar bucket; use a UTC time key for this range.' ELSE '0' END AS integer) + CAST(CASE WHEN _hq_lower > _hq_upper THEN '[hypequery] Window measure time range must be non-empty and ordered.' ELSE '0' END AS integer) + 0 = 1) SELECT "period", "rollingP95", "rollingTop" FROM _hq_result ORDER BY "period" ASC LIMIT 501

